
import { GoogleGenAI } from "@google/genai";

/**
 * Generates a chat response using the Gemini API.
 * Uses gemini-3-flash-preview for general text-based chat assistance.
 * 
 * @param history - Array of previous messages in the conversation, formatted as Content objects.
 * @param message - The latest message from the user.
 * @returns The response text generated by the Gemini model.
 */
export async function getChatResponse(history: any[], message: string): Promise<string> {
  // Always create a new instance to ensure we have the most current API key and configuration.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // Gemini's contents array must follow specific rules (alternating roles, starting with 'user').
    // We filter out the initial 'model' greeting from the history if present, as it can confuse the start of the session.
    const contents = history.filter((item, index) => {
      if (index === 0 && item.role === 'model') return false;
      return true;
    });

    // Append the current user message to the conversation context.
    contents.push({
      role: 'user',
      parts: [{ text: message }]
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: "You are 'Scrappy', a helpful AI assistant for ScrapSeva, a platform that connects scrap sellers with collectors in India. Assist users with scrap prices (raddi rates), recycling tips, and how to use the app for scheduling pickups. Be concise, professional, and encourage eco-friendly habits.",
      },
    });

    // Access the generated text via the .text property as per guidelines.
    const text = response.text || "I'm sorry, I couldn't generate a response. Please try again.";
    return text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm experiencing some technical difficulties right now. Please try again in a moment!";
  }
}
